[ -z "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" ] || { echo "list --room with other date"; fail=1; }
e=$(mktemp)
BOOKINGS=$t bash src/list.sh --room >/dev/null 2>"$e"; rc=$?
[ $rc = 2 ] && [ "$(cat "$e")" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
rm -f "$e"
rm -f "$t"; exit $fail

e=$(mktemp)
BOOKINGS=$t bash src/list.sh 2026/11/10 >/dev/null 2>"$e"; rc=$?
[ $rc = 2 ] && [ "$(cat "$e")" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-13-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "list month 13"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-01-32 >/dev/null 2>&1; [ $? = 2 ] || { echo "list day 32"; fail=1; }
rm -f "$e"
rm -f "$t"; exit $fail

